WITH recent_subscriptions AS (SELECT * FROM subscriptions WHERE status = 'CANCELLED' AND customer_id = 26), summary AS (SELECT status, plan, MAX(monthly_fee) - MIN(monthly_fee) AS monthly_fee_range, COUNT(DISTINCT monthly_fee) AS unique_customers FROM recent_subscriptions GROUP BY status, plan) SELECT status, monthly_fee_range, unique_customers FROM summary WHERE unique_customers > 8 ORDER BY unique_customers DESC, status;
